import { createClient } from "https://esm.sh/@supabase/supabase-js@2.119.0";
const SUPABASE_URL="https://ufdkwsotyvwufvkucoyc.supabase.co";
const SUPABASE_PUBLISHABLE_KEY="sb_publishable_JDGTO6zXsK3sxZOnQFmqpQ_DuNT3nYX";
const supabaseClient=createClient(SUPABASE_URL,SUPABASE_PUBLISHABLE_KEY,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true}});
const SYNC_TABLE="arhm_sync_records", PENDING_BASE="arhmSyncPending_v1_";let activeUserId=null,realtimeChannel=null,pendingWrites={};
function authMessage(text){document.getElementById("authMessage").textContent=text||""}
function syncNotice(text){let el=document.getElementById("syncNotice");el.textContent=text||"";el.classList.toggle("visible",!!text)}
function pendingKey(bucket,id){return `${bucket}::${id}`}
function persistPending(){if(activeUserId)localStorage.setItem(PENDING_BASE+activeUserId,JSON.stringify(pendingWrites))}
async function putRecord(bucket,recordId,payload){if(!activeUserId)return;let id=String(recordId),key=pendingKey(bucket,id);pendingWrites[key]={bucket,record_id:id,payload};persistPending();try{let{error}=await supabaseClient.from(SYNC_TABLE).upsert({user_id:activeUserId,bucket,record_id:id,payload,updated_at:new Date().toISOString()},{onConflict:"user_id,bucket,record_id"});if(error)throw error;delete pendingWrites[key];persistPending();if(!Object.keys(pendingWrites).length)syncNotice("")}catch(e){syncNotice("Offline or sync unavailable. This device has kept your changes and will retry when it reconnects.")}}
async function flushPending(){if(!activeUserId||!navigator.onLine)return;for(const[key,row]of Object.entries(pendingWrites)){try{let{error}=await supabaseClient.from(SYNC_TABLE).upsert({user_id:activeUserId,...row,updated_at:new Date().toISOString()},{onConflict:"user_id,bucket,record_id"});if(error)throw error;delete pendingWrites[key];persistPending()}catch(e){syncNotice("Some changes are waiting to sync. Check your connection and try again.");return}}if(!Object.keys(pendingWrites).length)syncNotice("")}
async function deleteBucket(bucket){if(!activeUserId)return;try{let{error}=await supabaseClient.from(SYNC_TABLE).delete().eq("user_id",activeUserId).eq("bucket",bucket);if(error)throw error;syncNotice("")}catch(e){syncNotice("Could not sync the reset yet. It will need an internet connection to reach your other device.")}}
window.addEventListener("online",()=>void flushPending());
function localRecords(){let rows=[];for(const[i,payload]of Object.entries(raceState||{}))rows.push({bucket:"race",record_id:i,payload});for(const[i,payload]of Object.entries(expoState||{}))rows.push({bucket:"expo",record_id:i,payload});contactData=contactData.map((c,i)=>({...c,id:c.id||`role_${i}`,order:c.order??i}));localStorage.setItem(CONTACT_KEY,JSON.stringify(contactData));contactData.forEach(c=>rows.push({bucket:"contacts",record_id:c.id,payload:c}));bikers.forEach((b,i)=>rows.push({bucket:"bikers",record_id:String(i),payload:b}));for(let i=0;i<localStorage.length;i++){let key=localStorage.key(i);if(key&&key.startsWith("place_")){let m=key.match(/^place_(\d+)_(\d+)$/);if(m){let value=localStorage.getItem(key)||"";if(value)rows.push({bucket:"places",record_id:`${m[1]}_${m[2]}`,payload:{value}})}}}return rows}
function applyRemoteRows(rows){raceState={};expoState={};contactData=[];bikers=BIKER_ASSIGNMENTS.map((assignment,i)=>({assignment,name:"",mobile:"",callsign:"",share:"Not started",checkin:"",notes:""}));for(let i=localStorage.length-1;i>=0;i--){let k=localStorage.key(i);if(k&&k.startsWith("place_"))localStorage.removeItem(k)}for(const r of rows){if(r.bucket==="race")raceState[r.record_id]=r.payload;else if(r.bucket==="expo")expoState[r.record_id]=r.payload;else if(r.bucket==="contacts")contactData.push({...r.payload,id:r.record_id});else if(r.bucket==="bikers")bikers[Number(r.record_id)]=r.payload;else if(r.bucket==="places"){let[m,n]=r.record_id.split("_");localStorage.setItem(`place_${m}_${n}`,r.payload.value||"")}}contactData.sort((a,b)=>(a.order??0)-(b.order??0));if(!contactData.length)contactData=DEFAULT_ROLES.map((role,i)=>({id:`role_${i}`,order:i,role,name:"",mobile:"",backup:"",area:""}));localStorage.setItem(KEY,JSON.stringify(raceState));localStorage.setItem(EXPO_KEY,JSON.stringify(expoState));localStorage.setItem(CONTACT_KEY,JSON.stringify(contactData));localStorage.setItem(BIKER_KEY,JSON.stringify(bikers));void putRecord('bikers',String(i),bikers[i]);state=activeMode==="expo"?expoState:raceState}
function applyRemoteRecord(r){if(!r||!r.bucket)return;let id=String(r.record_id),p=r.payload;if(r.bucket==="race"||r.bucket==="expo"){let target=r.bucket==="race"?raceState:expoState;target[id]=p;localStorage.setItem(r.bucket==="race"?KEY:EXPO_KEY,JSON.stringify(target));if(activeMode===r.bucket){state=target;renderTasks()}}else if(r.bucket==="contacts"){let i=contactData.findIndex(c=>c.id===id);if(i<0)contactData.push({...p,id});else contactData[i]={...p,id};contactData.sort((a,b)=>(a.order??0)-(b.order??0));localStorage.setItem(CONTACT_KEY,JSON.stringify(contactData));renderContacts()}else if(r.bucket==="bikers"){bikers[Number(id)]=p;localStorage.setItem(BIKER_KEY,JSON.stringify(bikers));void putRecord('bikers',String(i),bikers[i]);renderBikers()}else if(r.bucket==="places"){let[m,n]=id.split("_");localStorage.setItem(`place_${m}_${n}`,p.value||"");if(Number(m)===activeMap)renderPoints()}}
function applyRemoteDelete(r){if(!r)return;let id=String(r.record_id);if(r.bucket==="race"||r.bucket==="expo"){let target=r.bucket==="race"?raceState:expoState;delete target[id];localStorage.setItem(r.bucket==="race"?KEY:EXPO_KEY,JSON.stringify(target));if(activeMode===r.bucket){state=target;renderTasks()}}}
async function startApp(){authMessage("");let{data:{session},error:sessionError}=await supabaseClient.auth.getSession();if(sessionError||!session){document.getElementById("appShell").hidden=true;document.getElementById("authGate").hidden=false;authMessage(sessionError?.message||"");return}activeUserId=session.user.id;pendingWrites=JSON.parse(localStorage.getItem(PENDING_BASE+activeUserId)||"{}");let{data:rows,error}=await supabaseClient.from(SYNC_TABLE).select("bucket,record_id,payload").eq("user_id",activeUserId);if(error){syncNotice("Could not reach Supabase. This device will keep local changes and retry when the connection returns.")}else if(!rows.length){let seeds=localRecords();applyRemoteRows(seeds);if(seeds.length){let{error:seedError}=await supabaseClient.from(SYNC_TABLE).upsert(seeds.map(r=>({...r,user_id:activeUserId,updated_at:new Date().toISOString()})),{onConflict:"user_id,bucket,record_id"});if(seedError){for(const r of seeds)pendingWrites[pendingKey(r.bucket,r.record_id)]=r;persistPending();syncNotice("Initial sync is waiting for a connection.")}}}else{applyRemoteRows(rows);for(const r of Object.values(pendingWrites))applyRemoteRecord(r)}document.getElementById("authGate").hidden=true;document.getElementById("appShell").hidden=false;initializeApp();subscribeRealtime();void flushPending()}
function subscribeRealtime(){if(!activeUserId)return;if(realtimeChannel)supabaseClient.removeChannel(realtimeChannel);realtimeChannel=supabaseClient.channel(`arhm-sync-${activeUserId}`).on("postgres_changes",{event:"*",schema:"public",table:SYNC_TABLE,filter:`user_id=eq.${activeUserId}`},payload=>{let row=payload.new||payload.old;if(!row)return;let key=pendingKey(row.bucket,String(row.record_id));if(pendingWrites[key])return;if(payload.eventType==="DELETE")applyRemoteDelete(row);else applyRemoteRecord(row)}).subscribe(status=>{if(status==="CHANNEL_ERROR"||status==="TIMED_OUT")syncNotice("Live sync paused. Your edits remain saved here and will retry when connected.")})}
