function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function attr(s){return esc(s||'')}
function renderBikers(){const box=document.getElementById('bikerCards');box.innerHTML='';bikers.forEach((b,i)=>{let card=document.createElement('div');card.className='bikercard';card.innerHTML=`<div class="bikertop"><strong>Biker ${String(i+1).padStart(2,'0')}</strong><span class="contactsstatus">${i<6?'Leader coverage':'Flexible role'}</span></div><div class="bikerfields"><label class="wide">Category / assignment<input data-k="assignment" value="${attr(b.assignment)}"></label><label>Rider in-charge<input data-k="name" value="${attr(b.name)}" placeholder="Full name"></label><label>Mobile number<input data-k="mobile" value="${attr(b.mobile)}" placeholder="Phone"></label><label>Radio call sign<input data-k="callsign" value="${attr(b.callsign)}" placeholder="Call sign"></label><label>WhatsApp Live Location<select data-k="share"><option${b.share==='Not started'?' selected':''}>Not started</option><option${b.share==='Sharing confirmed'?' selected':''}>Sharing confirmed</option><option${b.share==='No signal'?' selected':''}>No signal</option><option${b.share==='Stopped / expired'?' selected':''}>Stopped / expired</option></select></label><label>Last check-in time<input data-k="checkin" value="${attr(b.checkin)}" placeholder="Time"></label><label>Backup / notes<input data-k="notes" value="${attr(b.notes)}" placeholder="Backup contact or notes"></label></div>`;card.querySelectorAll('[data-k]').forEach(inp=>{let key=inp.dataset.k;inp.onchange=()=>{bikers[i][key]=inp.value;localStorage.setItem(BIKER_KEY,JSON.stringify(bikers));void putRecord('bikers',String(i),bikers[i])}});box.appendChild(card)})}
function saveContacts(changedId){localStorage.setItem(CONTACT_KEY,JSON.stringify(contactData));if(changedId){let c=contactData.find(x=>x.id===changedId);if(c)void putRecord('contacts',c.id,c)}let missing=contactData.filter(c=>!c.name||!c.mobile).length;document.getElementById('contactSummary').textContent=missing?`${missing} contacts need a name and phone`:'All contact names and phones filled'}
function renderContacts(){let box=document.getElementById('contactGrid');box.innerHTML='';contactData.forEach((c,i)=>{let row=document.createElement('div');row.className='contactrow';row.innerHTML=`<div class="contactrole">${esc(c.role)}</div>${[['name','Name'],['mobile','Mobile / radio'],['backup','Backup contact'],['area','Assigned area / post']].map(([key,label])=>`<label class="contactlabel">${label}<input aria-label="${esc(c.role)} ${label}" value="${attr(c[key])}" placeholder="Enter ${label.toLowerCase()}"></label>`).join('')}`;row.querySelectorAll('input').forEach((input,j)=>{let key=['name','mobile','backup','area'][j];input.onchange=()=>{contactData[i][key]=input.value;saveContacts(contactData[i].id)}});box.appendChild(row)});saveContacts()}
document.getElementById('addContact').onclick=()=>{let role=prompt('Enter the contact role or team name:');if(role&&role.trim()){let c={id:crypto.randomUUID(),order:Date.now(),role:role.trim(),name:'',mobile:'',backup:'',area:''};contactData.push(c);saveContacts(c.id);renderContacts()}};
