document.querySelectorAll('.mode-button').forEach(b=>b.onclick=()=>setMode(b.dataset.mode));document.querySelectorAll('.tabs button').forEach(b=>b.onclick=()=>{activeMap=+b.dataset.map;document.querySelectorAll('.tabs button').forEach(x=>x.classList.toggle('active',x===b));renderPoints()});document.getElementById('search').oninput=renderTasks;document.getElementById('statusFilter').onchange=renderTasks;document.getElementById('reset').onclick=()=>{if(confirm('Clear all statuses, owners and notes for this checklist?'))resetChecklist(activeMode)};document.getElementById('export').onclick=()=>{let rows=[['Section','Position','Task','Status','Owner','Note']];TASKS.forEach((x,i)=>{let d=get(i);rows.push([x.section,x.position,x.task,d.status,d.owner,d.note])});let csv=rows.map(r=>r.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\n');let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download='ARHM-checklist-status.csv';a.click();URL.revokeObjectURL(a.href)};
